import { apiClient } from './api'
import type { ExplanationConsistencyResponse, ExplanationResponse } from '../types/api'

// The backend generates and persists SHAP; this client submits only the linked IDs.
export async function generateShapExplanation(
  patientId: number,
  recordId: number,
  predictionId: number,
): Promise<ExplanationResponse> {
  const response = await apiClient.post<ExplanationResponse>(
    `/patients/${patientId}/records/${recordId}/predictions/${predictionId}/explanation/shap`,
  )
  return response.data
}

// LIME is generated by the backend for the same stored record and prediction.
export async function generateLimeExplanation(
  patientId: number,
  recordId: number,
  predictionId: number,
): Promise<ExplanationResponse> {
  const response = await apiClient.post<ExplanationResponse>(
    `/patients/${patientId}/records/${recordId}/predictions/${predictionId}/explanation/lime`,
  )
  return response.data
}

// The backend computes comparison metrics for this prediction instance.
export async function getExplanationConsistency(
  patientId: number,
  recordId: number,
  predictionId: number,
): Promise<ExplanationConsistencyResponse> {
  const response = await apiClient.get<ExplanationConsistencyResponse>(
    `/patients/${patientId}/records/${recordId}/predictions/${predictionId}/explanation/consistency`,
  )
  return response.data
}
